insert into competencias (nome, tipo, definicao) values
('Conhecimento da função', 'tecnica', 'Demonstra domínio dos conhecimentos, processos, ferramentas e procedimentos necessários para executar adequadamente as atividades de sua função.'),
('Qualidade das atividades', 'tecnica', 'Executa suas atividades com precisão, consistência e atenção aos padrões estabelecidos, buscando reduzir erros, retrabalhos e falhas.'),
('Produtividade', 'tecnica', 'Realiza suas atividades com eficiência, utilizando adequadamente o tempo e os recursos disponíveis e mantendo um nível de entrega compatível com as demandas da função.'),
('Cumprimento de prazos', 'tecnica', 'Organiza e executa suas atividades de forma a atender aos prazos estabelecidos, sinalizando antecipadamente eventuais riscos ou dificuldades que possam comprometer as entregas.'),
('Solução de problemas', 'tecnica', 'Identifica causas, analisa alternativas e propõe soluções adequadas para problemas relacionados às suas atividades, atuando de forma prática e fundamentada.'),
('Aprendizagem contínua', 'tecnica', 'Busca desenvolver e atualizar seus conhecimentos e habilidades, aplicando novos aprendizados para melhorar sua atuação profissional.'),
('Atenção aos detalhes', 'tecnica', 'Observa informações, dados, procedimentos e requisitos relevantes para a execução das atividades, identificando inconsistências e evitando erros que possam impactar o resultado.'),
('Melhoria contínua', 'tecnica', 'Identifica oportunidades de aprimoramento em processos, métodos e rotinas de trabalho e contribui com sugestões e ações que aumentem a eficiência, qualidade ou produtividade.');
